    width = observation.get("width", 0)
    height = observation.get("height", 0)
    # Get agent's position
    my_pos = observation.get("position", None)
    if my_pos is None:
        return [0, 0]
    my_x, my_y = my_pos

    # Helper to find positions of a type
    def find_positions(entity_type):
        return [
            (pos.get("x"), pos.get("y"))
            for pos in observation.get("entities", [])
            if pos.get("type") == entity_type
        ]

    # Defensive fetching
    resources = find_positions("resource")
    opponents = find_positions("enemy")
    territory_owners = []
    if "territory" in observation:
        for terr in observation["territory"]:
            if terr.get("owner") != "self":
                territory_owners.append((terr.get("x"), terr.get("y")))

    # Initialize move vector
    dx, dy = 0, 0

    # Determine closest resource
    def distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    target = None
    min_dist = float('inf')
    for res in resources:
        dist = distance(my_pos, res)
        if dist < min_dist:
            min_dist = dist
            target = res

    # Movement towards target if exists
    if target:
        delta_x = target[0] - my_x
        delta_y = target[1] - my_y
        # Decide move in x
        if delta_x != 0:
            dx = 1 if delta_x > 0 else -1
        # Decide move in y
        elif delta_y != 0:
            dy = 1 if delta_y > 0 else -1

    # If no resource, check for opponents (pursuit)
    elif opponents:
        for opp in opponents:
            dist = distance(my_pos, opp)
            if dist <= 3:
                delta_x = opp[0] - my_x
                delta_y = opp[1] - my_y
