                    dx = 1 if delta_x > 0 else -1
                elif delta_y != 0:
                    dy = 1 if delta_y > 0 else -1
                break
    # Territory control: move to nearest enemy territory
    elif territory_owners:
        closest_territory = None
        min_t_dist = float('inf')
